export const names=['Jade Statue','Pathway Arrows','Gremlin Mine','Field of the Dead','Campfire','Elixir','Shield of Kaldra','Shield of the Avatar',"Warmonger's Chariot",'Sting, the Glinting Dagger','Seraphic Greatsword',"Staff of Eden, Vault's Key",'Guidelight Matrix','Auxiliary Boosters','The Black Arrow','Mirror Shield','Dragonspark Reactor','Purging Scythe','Portal to Phyrexia','Haunted Plate Mail','Spawning Pool','Bottled Cloister','Moonring Mirror','Pyxis of Pandemonium','Sphere of Annihilation','Helm of Kaldra','Wishclaw Talisman','Bronze Cudgels','Daredevil Dragster'];
