// These complete paid traces establish every printed clause, including native
// operations whose shared generic driver cannot stage their exact prerequisites.
const wholePaidNativeV60=new Set(["Altar of Bhaal // Bone Offering", "Blitzball", "Dawn-Blessed Pennant", "Eclipsed Realms", "Ether", "Infinite Hourglass", "Konda's Banner", "Stardew Valley", "Three Tree City", "Tsabo's Web"]);
export async function operationProofV60(M,entry,op,role,h){if(!names.includes(entry.raw.name)||!wholePaidNativeV60.has(entry.raw.name)&&!JSON.stringify(op).includes('v60')&&!JSON.stringify(op).includes('V60'))return null;let count=0;const assert=Object.fromEntries(['ok','equal','deepEqual'].map(k=>[k,(...args)=>{count++;strict[k](...args);} ]));for(const positive of [true,false])await proveCommonV60(M,entry.raw.name,role,positive,h,assert);return count;}
